import { AxisScale } from '@visx/axis';
import { scaleTime } from '@visx/scale';

import type { Timeseries } from '../../core/types/timeseries.js';

export const getSparklineXScale = (
  data: Timeseries,
  width: number,
  padding: number,
): AxisScale<number> => {
  const timestamps = data.datapoints.map(
    (datapoint) => datapoint.end?.getTime() ?? datapoint.start.getTime(),
  );

  return scaleTime({
    domain: [Math.min(...timestamps), Math.max(...timestamps)],
    range: [padding, width - padding],
  });
};
